insert into public.pulse_challenge_templates (id, code, title, description, category, difficulty, points, answer_type, options, scoring_rule, required_facts, active, priority, cooldown_days, tags)
select 'cht_' || lower(code), code, title, description, category, difficulty, points, "answerType", options, rule, array['home_score','away_score']::text[], true, priority, cooldown, array(select jsonb_array_elements_text(tags))
from jsonb_to_recordset($json$[{"code":"TOTAL_LTE_8","title":"¿Habrá 8 o menos carreras en total?","description":"Se corrige con el marcador final.","category":"total","difficulty":"easy","points":2,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"total_lte","n":8},"priority":0,"cooldown":2,"tags":["total"]},{"code":"TOTAL_LTE_9","title":"¿Se quedan en 9 carreras o menos?","description":"Se corrige con el marcador final.","category":"total","difficulty":"medium","points":4,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"total_lte","n":9},"priority":0,"cooldown":2,"tags":["total"]},{"code":"TOTAL_EQ_6","title":"¿El total será exactamente 6 carreras?","description":"Se corrige con el marcador final.","category":"dificultad","difficulty":"expert","points":10,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"total_eq","n":6},"priority":0,"cooldown":2,"tags":["dificultad"]},{"code":"TOTAL_EQ_7","title":"¿El total será exactamente 7 carreras?","description":"Se corrige con el marcador final.","category":"dificultad","difficulty":"expert","points":10,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"total_eq","n":7},"priority":0,"cooldown":2,"tags":["dificultad"]}]$json$::jsonb) as t(code text, title text, description text, category text, difficulty text, points int, "answerType" text, options jsonb, rule jsonb, priority int, cooldown int, tags jsonb)
on conflict (code) do nothing;